(function(){
"use strict";

// ===== lab-shell.mjs =====
// lab-shell.mjs — pure, framework-free zsh emulator core.
//
// An in-memory filesystem (nested Maps for directories, strings for files)
// plus a small command interpreter covering exactly the commands the
// ISM3232 shell labs use. No DOM, no dependencies. Consumed by the reveal.js
// terminal widget (Task 5) and unit-tested directly with `node --test`.
//
// Exports: createShell(seed) -> shell
//          run(shell, line)  -> { out, err, cleared }
//          prompt(shell)     -> string
//          listing(shell, path?) -> string[]

const HOME = '/Users/student';
const HOSTNAME = 'MacBook-Pro';
const USER = 'student';
const STAMP = 'Sep  5 10:00';

const KNOWN_COMMANDS = new Set([
  'pwd', 'ls', 'cd', 'mkdir', 'touch', 'cat', 'echo', 'rm', 'cp', 'mv',
  'tree', 'head', 'tail', 'wc', 'clear', 'whoami', 'which', 'history',
  'code', 'python3',
]);

// ---------------------------------------------------------------------------
// Path helpers
// ---------------------------------------------------------------------------

function normalize(p) {
  const parts = p.split('/').filter((x) => x !== '' && x !== '.');
  const stack = [];
  for (const part of parts) {
    if (part === '..') stack.pop();
    else stack.push(part);
  }
  return '/' + stack.join('/');
}

function resolvePath(shell, p) {
  if (p === undefined || p === null || p === '') return shell.cwd;
  let base;
  if (p === '~') base = HOME;
  else if (p.startsWith('~/')) base = HOME + '/' + p.slice(2);
  else if (p.startsWith('/')) base = p;
  else base = shell.cwd + '/' + p;
  return normalize(base);
}

// macOS's default locale sorts filenames case-insensitively (so `ls` shows
// `hello.py` before `README.md`), unlike a raw JS codepoint `.sort()` which
// orders all capitals ahead of all lowercase. The shell labs compare the
// emulator's output to a stock macOS terminal, so fold case first. Comparison
// is still codepoint-wise on the lowercased names (NOT localeCompare, whose
// locale collation reweights punctuation and would put `notes_backup.txt`
// before `notes.txt`); original case only breaks an exact fold tie.
function sortNames(names) {
  return [...names].sort((a, b) => {
    const la = a.toLowerCase();
    const lb = b.toLowerCase();
    if (la < lb) return -1;
    if (la > lb) return 1;
    return a < b ? -1 : a > b ? 1 : 0;
  });
}

function basename(p) {
  const parts = p.split('/').filter(Boolean);
  return parts.length ? parts[parts.length - 1] : '/';
}

function parentPath(p) {
  const parts = p.split('/').filter(Boolean);
  parts.pop();
  return '/' + parts.join('/');
}

// ---------------------------------------------------------------------------
// Filesystem helpers (root is a Map)
// ---------------------------------------------------------------------------

function nodeAt(root, path) {
  if (path === '/' || path === '') return root;
  const parts = path.split('/').filter(Boolean);
  let node = root;
  for (const part of parts) {
    if (!(node instanceof Map) || !node.has(part)) return null;
    node = node.get(part);
  }
  return node;
}

function mkdirp(root, path) {
  const parts = path.split('/').filter(Boolean);
  let node = root;
  for (const part of parts) {
    if (!node.has(part)) node.set(part, new Map());
    node = node.get(part);
    if (!(node instanceof Map)) return null; // collided with a file
  }
  return node;
}

function deepCopy(node) {
  if (!(node instanceof Map)) return node; // string files are immutable values
  const copy = new Map();
  for (const [k, v] of node) copy.set(k, deepCopy(v));
  return copy;
}

function buildSeed(root, obj, basePath) {
  for (const [key, val] of Object.entries(obj)) {
    let keyPath = key;
    if (keyPath.startsWith('~')) keyPath = HOME + keyPath.slice(1);
    const full = keyPath.startsWith('/') ? keyPath : basePath + '/' + keyPath;
    const norm = normalize(full);
    if (typeof val === 'string') {
      mkdirp(root, parentPath(norm));
      const parent = nodeAt(root, parentPath(norm));
      if (parent instanceof Map) parent.set(basename(norm), val);
    } else if (val && typeof val === 'object') {
      mkdirp(root, norm);
      buildSeed(root, val, norm);
    }
  }
}

// ---------------------------------------------------------------------------
// Tokenizer — honors single and double quotes; treats > >> | as operators.
// ---------------------------------------------------------------------------

function tokenize(line) {
  const tokens = [];
  let cur = '';
  let hasCur = false;
  const flush = () => {
    if (hasCur) {
      tokens.push({ type: 'word', value: cur });
      cur = '';
      hasCur = false;
    }
  };
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === ' ' || c === '\t') {
      flush();
      continue;
    }
    if (c === "'") {
      hasCur = true;
      i++;
      while (i < line.length && line[i] !== "'") cur += line[i++];
      continue;
    }
    if (c === '"') {
      hasCur = true;
      i++;
      while (i < line.length && line[i] !== '"') cur += line[i++];
      continue;
    }
    if (c === '|') {
      flush();
      tokens.push({ type: 'op', value: '|' });
      continue;
    }
    if (c === '>') {
      flush();
      if (line[i + 1] === '>') {
        tokens.push({ type: 'op', value: '>>' });
        i++;
      } else {
        tokens.push({ type: 'op', value: '>' });
      }
      continue;
    }
    cur += c;
    hasCur = true;
  }
  flush();
  return tokens;
}

// ---------------------------------------------------------------------------
// Content helpers
// ---------------------------------------------------------------------------

function splitLines(content) {
  const lines = content.split('\n');
  if (lines.length && lines[lines.length - 1] === '') lines.pop();
  return lines;
}

function joinLines(lines) {
  return lines.length ? lines.join('\n') + '\n' : '';
}

// ---------------------------------------------------------------------------
// createShell
// ---------------------------------------------------------------------------

function createShell(seed) {
  const root = new Map();
  mkdirp(root, HOME);
  if (seed && typeof seed === 'object') buildSeed(root, seed, HOME);
  mkdirp(root, HOME); // ensure it still exists

  return {
    cwd: HOME,
    home: HOME,
    prev: HOME,
    history: [],
    _fs: root,
  };
}

// ---------------------------------------------------------------------------
// Commands — each returns { out, err } (and optionally cleared).
// ---------------------------------------------------------------------------

function cmd_pwd(shell) {
  return { out: shell.cwd + '\n', err: '' };
}

function cmd_cd(shell, args) {
  const target = args[0];
  if (target === undefined || target === '~') {
    shell.prev = shell.cwd;
    shell.cwd = HOME;
    return { out: '', err: '' };
  }
  if (target === '-') {
    const dest = shell.prev;
    shell.prev = shell.cwd;
    shell.cwd = dest;
    return { out: shell.cwd + '\n', err: '' };
  }
  const path = resolvePath(shell, target);
  const node = nodeAt(shell._fs, path);
  if (!(node instanceof Map)) {
    return { out: '', err: `cd: no such file or directory: ${target}\n` };
  }
  shell.prev = shell.cwd;
  shell.cwd = path;
  return { out: '', err: '' };
}

function parseLsFlags(args) {
  let long = false;
  let all = false;
  const paths = [];
  for (const a of args) {
    if (a.startsWith('-') && a.length > 1) {
      for (const ch of a.slice(1)) {
        if (ch === 'l') long = true;
        else if (ch === 'a') all = true;
      }
    } else {
      paths.push(a);
    }
  }
  return { long, all, paths };
}

function lsLongBlock(map, parentMap, all) {
  const names = sortNames(
    [...map.keys()].filter((n) => all || !n.startsWith('.')),
  );
  const entries = [];
  if (all) {
    entries.push(['.', map]);
    entries.push(['..', parentMap || map]);
  }
  for (const n of names) entries.push([n, map.get(n)]);
  const lines = ['total ' + entries.length];
  for (const [n, node] of entries) {
    const isDir = node instanceof Map;
    const perms = isDir ? 'drwxr-xr-x' : '-rw-r--r--';
    const size = isDir ? 64 : String(node).length;
    lines.push(`${perms}  1 ${USER}  staff  ${size}  ${STAMP} ${n}`);
  }
  return lines.join('\n') + '\n';
}

function cmd_ls(shell, args) {
  const { long, all, paths } = parseLsFlags(args);
  const targetArg = paths[0];
  const path = targetArg ? resolvePath(shell, targetArg) : shell.cwd;
  const node = nodeAt(shell._fs, path);
  if (node === null) {
    return { out: '', err: `ls: ${targetArg}: No such file or directory\n` };
  }
  if (!(node instanceof Map)) {
    // a file path
    if (long) {
      return {
        out: `-rw-r--r--  1 ${USER}  staff  ${String(node).length}  ${STAMP} ${basename(path)}\n`,
        err: '',
      };
    }
    return { out: basename(path) + '\n', err: '' };
  }
  if (long) {
    const parent = nodeAt(shell._fs, parentPath(path));
    return { out: lsLongBlock(node, parent, all), err: '' };
  }
  let names = sortNames(
    [...node.keys()].filter((n) => all || !n.startsWith('.')),
  );
  if (all) names = ['.', '..', ...names];
  return { out: names.length ? names.join('  ') + '\n' : '', err: '' };
}

function cmd_mkdir(shell, args) {
  const recursive = args.includes('-p');
  const targets = args.filter((a) => a !== '-p');
  let err = '';
  for (const t of targets) {
    const path = resolvePath(shell, t);
    if (recursive) {
      if (mkdirp(shell._fs, path) === null) {
        err += `mkdir: ${t}: Not a directory\n`;
      }
      continue;
    }
    const parent = nodeAt(shell._fs, parentPath(path));
    if (!(parent instanceof Map)) {
      err += `mkdir: ${t}: No such file or directory\n`;
      continue;
    }
    if (parent.has(basename(path))) {
      err += `mkdir: ${t}: File exists\n`;
      continue;
    }
    parent.set(basename(path), new Map());
  }
  return { out: '', err };
}

function cmd_touch(shell, args) {
  let err = '';
  for (const t of args) {
    const path = resolvePath(shell, t);
    const parent = nodeAt(shell._fs, parentPath(path));
    if (!(parent instanceof Map)) {
      err += `touch: ${t}: No such file or directory\n`;
      continue;
    }
    if (!parent.has(basename(path))) parent.set(basename(path), '');
  }
  return { out: '', err };
}

function cmd_cat(shell, args, pipeInput) {
  if (args.length === 0 && pipeInput !== null) {
    return { out: pipeInput, err: '' };
  }
  let out = '';
  let err = '';
  for (const a of args) {
    const path = resolvePath(shell, a);
    const node = nodeAt(shell._fs, path);
    if (node === null) {
      err += `cat: ${a}: No such file or directory\n`;
    } else if (node instanceof Map) {
      err += `cat: ${a}: Is a directory\n`;
    } else {
      out += node;
    }
  }
  return { out, err };
}

function cmd_echo(shell, args) {
  return { out: args.join(' ') + '\n', err: '' };
}

function cmd_rm(shell, args) {
  const recursive = args.some((a) => a === '-r' || a === '-rf' || a === '-fr' || a === '-f');
  const targets = args.filter((a) => !a.startsWith('-'));
  let err = '';
  for (const t of targets) {
    const path = resolvePath(shell, t);
    const parent = nodeAt(shell._fs, parentPath(path));
    const node = parent instanceof Map ? parent.get(basename(path)) : undefined;
    if (node === undefined) {
      err += `rm: ${t}: No such file or directory\n`;
      continue;
    }
    if (node instanceof Map && !recursive) {
      err += `rm: ${t}: is a directory\n`;
      continue;
    }
    parent.delete(basename(path));
  }
  return { out: '', err };
}

function resolveDest(shell, srcPath, destArg) {
  const destPath = resolvePath(shell, destArg);
  const destNode = nodeAt(shell._fs, destPath);
  if (destNode instanceof Map) {
    return destPath + '/' + basename(srcPath);
  }
  return destPath;
}

function cmd_cp(shell, args) {
  const recursive = args.some((a) => a === '-r' || a === '-R');
  const rest = args.filter((a) => !a.startsWith('-'));
  const [srcArg, destArg] = rest;
  if (!srcArg || !destArg) return { out: '', err: 'usage: cp source target\n' };
  const srcPath = resolvePath(shell, srcArg);
  const srcNode = nodeAt(shell._fs, srcPath);
  if (srcNode === null) {
    return { out: '', err: `cp: ${srcArg}: No such file or directory\n` };
  }
  if (srcNode instanceof Map && !recursive) {
    return { out: '', err: `cp: ${srcArg}: is a directory\n` };
  }
  const finalPath = resolveDest(shell, srcPath, destArg);
  const parent = nodeAt(shell._fs, parentPath(finalPath));
  if (!(parent instanceof Map)) {
    return { out: '', err: `cp: ${destArg}: No such file or directory\n` };
  }
  parent.set(basename(finalPath), deepCopy(srcNode));
  return { out: '', err: '' };
}

function cmd_mv(shell, args) {
  const rest = args.filter((a) => !a.startsWith('-'));
  const [srcArg, destArg] = rest;
  if (!srcArg || !destArg) return { out: '', err: 'usage: mv source target\n' };
  const srcPath = resolvePath(shell, srcArg);
  const srcParent = nodeAt(shell._fs, parentPath(srcPath));
  const srcNode = srcParent instanceof Map ? srcParent.get(basename(srcPath)) : undefined;
  if (srcNode === undefined) {
    return { out: '', err: `mv: ${srcArg}: No such file or directory\n` };
  }
  const finalPath = resolveDest(shell, srcPath, destArg);
  const destParent = nodeAt(shell._fs, parentPath(finalPath));
  if (!(destParent instanceof Map)) {
    return { out: '', err: `mv: ${destArg}: No such file or directory\n` };
  }
  destParent.set(basename(finalPath), srcNode);
  srcParent.delete(basename(srcPath));
  return { out: '', err: '' };
}

function cmd_tree(shell, args) {
  let maxDepth = Infinity;
  let pathArg = null;
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '-L') {
      maxDepth = parseInt(args[++i], 10);
      if (Number.isNaN(maxDepth)) maxDepth = Infinity;
    } else if (!args[i].startsWith('-')) {
      pathArg = args[i];
    }
  }
  const path = pathArg ? resolvePath(shell, pathArg) : shell.cwd;
  const node = nodeAt(shell._fs, path);
  if (!(node instanceof Map)) {
    return { out: '', err: `${pathArg || '.'} [error opening dir]\n` };
  }
  const lines = [pathArg || '.'];
  const walk = (map, prefix, depth) => {
    if (depth > maxDepth) return;
    const keys = [...map.keys()];
    const dirs = sortNames(keys.filter((k) => map.get(k) instanceof Map));
    const files = sortNames(keys.filter((k) => !(map.get(k) instanceof Map)));
    const ordered = [...dirs, ...files];
    ordered.forEach((name, idx) => {
      const last = idx === ordered.length - 1;
      lines.push(prefix + (last ? '└── ' : '├── ') + name);
      const child = map.get(name);
      if (child instanceof Map) {
        walk(child, prefix + (last ? '    ' : '│   '), depth + 1);
      }
    });
  };
  walk(node, '', 1);
  return { out: lines.join('\n') + '\n\n', err: '' };
}

function parseCount(args, dflt) {
  let n = dflt;
  const files = [];
  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a === '-n') {
      const v = parseInt(args[++i], 10);
      if (!Number.isNaN(v)) n = v;
    } else if (/^-\d+$/.test(a)) {
      n = parseInt(a.slice(1), 10);
    } else if (!a.startsWith('-')) {
      files.push(a);
    }
  }
  return { n, files };
}

function readSource(shell, files, pipeInput) {
  if (files.length) {
    const path = resolvePath(shell, files[0]);
    const node = nodeAt(shell._fs, path);
    if (node === null) return { content: null, err: `${files[0]}: No such file or directory\n` };
    if (node instanceof Map) return { content: null, err: `${files[0]}: Is a directory\n` };
    return { content: node, err: '' };
  }
  return { content: pipeInput === null ? '' : pipeInput, err: '' };
}

function cmd_head(shell, args, pipeInput) {
  const { n, files } = parseCount(args, 10);
  const { content, err } = readSource(shell, files, pipeInput);
  if (content === null) return { out: '', err: 'head: ' + err };
  return { out: joinLines(splitLines(content).slice(0, n)), err: '' };
}

function cmd_tail(shell, args, pipeInput) {
  const { n, files } = parseCount(args, 10);
  const { content, err } = readSource(shell, files, pipeInput);
  if (content === null) return { out: '', err: 'tail: ' + err };
  return { out: joinLines(splitLines(content).slice(-n)), err: '' };
}

function cmd_wc(shell, args, pipeInput) {
  const lineMode = args.includes('-l');
  const files = args.filter((a) => !a.startsWith('-'));
  if (!files.length) {
    const content = pipeInput === null ? '' : pipeInput;
    const count = (content.match(/\n/g) || []).length;
    return { out: `${count}\n`, err: '' };
  }
  let out = '';
  let err = '';
  for (const f of files) {
    const path = resolvePath(shell, f);
    const node = nodeAt(shell._fs, path);
    if (node === null) {
      err += `wc: ${f}: No such file or directory\n`;
      continue;
    }
    if (node instanceof Map) {
      err += `wc: ${f}: read: Is a directory\n`;
      continue;
    }
    const lc = (node.match(/\n/g) || []).length;
    if (lineMode) {
      out += `${lc} ${f}\n`;
    } else {
      const wc = node.split(/\s+/).filter(Boolean).length;
      out += `${lc} ${wc} ${node.length} ${f}\n`;
    }
  }
  return { out, err };
}

function cmd_which(shell, args) {
  const name = args[0];
  if (!name) return { out: '', err: '' };
  if (KNOWN_COMMANDS.has(name)) return { out: `/usr/bin/${name}\n`, err: '' };
  return { out: `${name} not found\n`, err: '' };
}

function cmd_history(shell) {
  const lines = shell.history.map((h, i) => `  ${i + 1}  ${h}`);
  return { out: lines.length ? lines.join('\n') + '\n' : '', err: '' };
}

function cmd_code(shell, args) {
  return { out: `(VS Code would open: ${args[0] || '.'})\n`, err: '' };
}

// python3 <file.py>   — runs the file's stored contents
// python3 -c "<code>" — runs the literal code string, no FS lookup
//
// With no runner injected, returns the Task 1 stub string. When the reveal.js
// terminal widget sets shell.pythonRunner (src -> Promise<{out, err}> or
// Promise<string>), the source is handed to Pyodide and run() surfaces an
// `async` marker (a Promise resolving to { out, err }) that the widget awaits
// and appends. A missing file is a synchronous CPython-shaped error — no
// `async` key at all, so the widget has nothing to await.
function cmd_python3(shell, args) {
  if (!(shell && typeof shell.pythonRunner === 'function')) {
    return { out: '(python3 stub — wired to Pyodide in Task 5)\n', err: '' };
  }
  const argv = args || [];
  let src = null;
  const cIdx = argv.indexOf('-c');
  if (cIdx >= 0) {
    // The Python source is the next arg (already unquoted by the tokenizer).
    src = argv[cIdx + 1] === undefined ? '' : argv[cIdx + 1];
  } else {
    const file = argv.find((a) => !a.startsWith('-'));
    if (file === undefined) return { out: '', err: '' }; // bare `python3` — REPL, no-op
    const node = nodeAt(shell._fs, resolvePath(shell, file));
    if (typeof node !== 'string') {
      return {
        out: '',
        err: `python3: can't open file '${file}': [Errno 2] No such file or directory\n`,
      };
    }
    src = node;
  }
  return {
    out: '',
    err: '',
    async: Promise.resolve(shell.pythonRunner(src)).then((r) => {
      // Accept both the {out, err} shape and the legacy plain-string shape.
      if (r && typeof r === 'object') {
        return { out: r.out || '', err: r.err || '' };
      }
      return { out: r || '', err: '' };
    }),
  };
}

// ---------------------------------------------------------------------------
// Dispatch
// ---------------------------------------------------------------------------

function execCommand(shell, argv, pipeInput) {
  if (argv.length === 0) return { out: '', err: '', cleared: false };
  const [name, ...args] = argv;
  switch (name) {
    case 'pwd': return cmd_pwd(shell);
    case 'cd': return cmd_cd(shell, args);
    case 'ls': return cmd_ls(shell, args);
    case 'mkdir': return cmd_mkdir(shell, args);
    case 'touch': return cmd_touch(shell, args);
    case 'cat': return cmd_cat(shell, args, pipeInput);
    case 'echo': return cmd_echo(shell, args);
    case 'rm': return cmd_rm(shell, args);
    case 'cp': return cmd_cp(shell, args);
    case 'mv': return cmd_mv(shell, args);
    case 'tree': return cmd_tree(shell, args);
    case 'head': return cmd_head(shell, args, pipeInput);
    case 'tail': return cmd_tail(shell, args, pipeInput);
    case 'wc': return cmd_wc(shell, args, pipeInput);
    case 'clear': return { out: '', err: '', cleared: true };
    case 'whoami': return { out: `${USER}\n`, err: '' };
    case 'which': return cmd_which(shell, args);
    case 'history': return cmd_history(shell);
    case 'code': return cmd_code(shell, args);
    case 'python3': return cmd_python3(shell, args);
    default:
      return { out: '', err: `zsh: command not found: ${name}\n` };
  }
}

function writeRedirect(shell, file, append, data) {
  const path = resolvePath(shell, file);
  const parent = nodeAt(shell._fs, parentPath(path));
  if (!(parent instanceof Map)) {
    return `zsh: no such file or directory: ${file}\n`;
  }
  const name = basename(path);
  if (append && typeof parent.get(name) === 'string') {
    parent.set(name, parent.get(name) + data);
  } else {
    parent.set(name, data);
  }
  return '';
}

// ---------------------------------------------------------------------------
// run
// ---------------------------------------------------------------------------

function run(shell, line) {
  shell.history.push(line);
  const trimmed = String(line).trim();
  if (!trimmed) return { out: '', err: '', cleared: false };

  const tokens = tokenize(trimmed);

  // Split on a single pipe.
  const pipeIdx = tokens.findIndex((t) => t.type === 'op' && t.value === '|');
  let leftTokens;
  let rightTokens = null;
  if (pipeIdx >= 0) {
    leftTokens = tokens.slice(0, pipeIdx);
    rightTokens = tokens.slice(pipeIdx + 1);
  } else {
    leftTokens = tokens;
  }

  // Redirection applies to the final command in the line.
  const finalTokens = rightTokens || leftTokens;
  let redirect = null;
  const rIdx = finalTokens.findIndex(
    (t) => t.type === 'op' && (t.value === '>' || t.value === '>>'),
  );
  if (rIdx >= 0) {
    const fileTok = finalTokens[rIdx + 1];
    redirect = {
      append: finalTokens[rIdx].value === '>>',
      file: fileTok && fileTok.type === 'word' ? fileTok.value : null,
    };
    finalTokens.splice(rIdx);
  }

  const words = (toks) => toks.filter((t) => t.type === 'word').map((t) => t.value);

  let err = '';
  let result;
  if (rightTokens) {
    const leftRes = execCommand(shell, words(leftTokens), null);
    err += leftRes.err || '';
    result = execCommand(shell, words(finalTokens), leftRes.out);
  } else {
    result = execCommand(shell, words(finalTokens), null);
  }
  err += result.err || '';
  let out = result.out || '';

  if (redirect) {
    if (redirect.file === null) {
      err += 'zsh: parse error near `\\n\'\n';
    } else {
      const wErr = writeRedirect(shell, redirect.file, redirect.append, out);
      if (wErr) err += wErr;
      out = '';
    }
  }

  const ret = { out, err, cleared: !!result.cleared };
  if (result && result.async) ret.async = result.async;
  return ret;
}

// ---------------------------------------------------------------------------
// prompt / listing
// ---------------------------------------------------------------------------

function prompt(shell) {
  const base = shell.cwd === shell.home ? '~' : basename(shell.cwd);
  return `${USER}@${HOSTNAME} ${base} %`;
}

function listing(shell, path) {
  const target = path ? resolvePath(shell, path) : shell.cwd;
  const node = nodeAt(shell._fs, target);
  if (!(node instanceof Map)) return [];
  return sortNames([...node.keys()].filter((n) => !n.startsWith('.')));
}

// ===== lab-pyodide.mjs =====
// lab-pyodide.mjs — lazy Pyodide loader + a Python run harness.
//
// Browser-only (Pyodide is WebAssembly). NOT unit-tested under Node — only
// syntax-checked with `node --check`; the real behaviour is verified in the
// reveal.js browser harness (Task 6). The contract below is frozen so the
// interactive Python widgets (Tasks 5, 6, 8) can rely on it.
//
// Exports:
//   pyReady()                              -> Promise<Pyodide>
//   runPython(code, { stdin, onStatus })   -> Promise<{ stdout, stderr, ok }>
//   loadPackages(names)                    -> Promise<void>
//
// Pinned exactly to Pyodide 0.26.4 (script + indexURL on cdn.jsdelivr.net).

const PYODIDE_VERSION = '0.26.4';
const PYODIDE_JS_URL = `https://cdn.jsdelivr.net/pyodide/v${PYODIDE_VERSION}/full/pyodide.js`;
const PYODIDE_INDEX_URL = `https://cdn.jsdelivr.net/pyodide/v${PYODIDE_VERSION}/full/`;

// ---------------------------------------------------------------------------
// Singleton loader
// ---------------------------------------------------------------------------

let pyodidePromise = null; // cached Promise<Pyodide>; shared by concurrent callers
let booted = false; // flips true once a cold boot has completed

// Inject the CDN <script> exactly once. Guarded on window.loadPyodide so a
// page that already pulled pyodide.js in some other way is reused as-is.
function injectPyodideScript() {
  return new Promise((resolve, reject) => {
    if (typeof window !== 'undefined' && window.loadPyodide) {
      resolve();
      return;
    }
    const existing = document.querySelector('script[data-lab-pyodide]');
    if (existing) {
      existing.addEventListener('load', () => resolve());
      existing.addEventListener('error', () =>
        reject(new Error('Failed to load pyodide.js')),
      );
      return;
    }
    const s = document.createElement('script');
    s.src = PYODIDE_JS_URL;
    s.async = true;
    s.dataset.labPyodide = '1';
    s.addEventListener('load', () => resolve());
    s.addEventListener('error', () =>
      reject(new Error('Failed to load pyodide.js from ' + PYODIDE_JS_URL)),
    );
    document.head.appendChild(s);
  });
}

// Idempotent singleton. First call injects the script, calls loadPyodide once,
// and caches the promise. Concurrent callers get the same promise. A failed
// boot clears the cache so a later call can retry.
function pyReady() {
  if (!pyodidePromise) {
    pyodidePromise = (async () => {
      await injectPyodideScript();
      const pyodide = await window.loadPyodide({ indexURL: PYODIDE_INDEX_URL });
      booted = true;
      return pyodide;
    })();
    pyodidePromise.catch(() => {
      pyodidePromise = null;
    });
  }
  return pyodidePromise;
}

// await pyReady() then load one or more packages (pandas, matplotlib, ...).
async function loadPackages(names) {
  const pyodide = await pyReady();
  await pyodide.loadPackage(names);
}

// ---------------------------------------------------------------------------
// runPython
// ---------------------------------------------------------------------------

const RESTORE_INPUT_PY = `
import builtins as __b
if hasattr(__b, "__lab_saved_input__"):
    __b.input = __b.__lab_saved_input__
`;

const INSTALL_INPUT_PY = `
import builtins as __b
if not hasattr(__b, "__lab_saved_input__"):
    __b.__lab_saved_input__ = __b.input
def __lab_input(prompt=""):
    __line = __lab_next_line(str(prompt))
    if __line is None:
        raise EOFError("EOF when reading a line")
    return __line
__b.input = __lab_input
`;

const INSTALL_STREAMS_PY = `
import sys as __sys
class __LabStream:
    def __init__(self, __w):
        self.__w = __w
    def write(self, __s):
        self.__w(__s)
        return len(__s)
    def flush(self):
        pass
    def isatty(self):
        return False
__sys.__lab_saved_stdout = __sys.stdout
__sys.__lab_saved_stderr = __sys.stderr
__sys.stdout = __LabStream(__lab_write_out)
__sys.stderr = __LabStream(__lab_write_err)
`;

const RESTORE_STREAMS_PY = `
import sys as __sys
if hasattr(__sys, "__lab_saved_stdout"):
    __sys.stdout = __sys.__lab_saved_stdout
    __sys.stderr = __sys.__lab_saved_stderr
    del __sys.__lab_saved_stdout
    del __sys.__lab_saved_stderr
`;

// Run a snippet of user Python. Captures stdout/stderr into strings and feeds
// input() from `stdin` (a queue of lines). Never throws for a *Python* error —
// that comes back as { ok: false, stderr: <traceback> }. Only rejects if the
// harness itself (loader, network) fails.
async function runPython(code, { stdin = [], onStatus } = {}) {
  const cold = !booted;
  if (cold) {
    try {
      onStatus && onStatus('loading');
    } catch (_) {
      /* onStatus must never break a run */
    }
  }
  const pyodide = await pyReady();
  if (cold) {
    try {
      onStatus && onStatus('ready');
    } catch (_) {
      /* ignore */
    }
  }

  let stdoutBuf = '';
  let stderrBuf = '';
  const queue = [...stdin]; // shift off a COPY; caller's array is untouched

  // `hasSetStreams` and `ns` are read by the `finally` below, so they live in
  // the function scope. Everything that mutates the shared Pyodide singleton
  // (stream redirection + the `input` override) happens INSIDE the `try`, so
  // the `finally` restore path runs even if a setup step throws or rejects.
  let hasSetStreams = false;
  let ns = null; // fresh per-run globals dict (PyProxy) — destroyed in finally
  let ok = true;
  try {
    // --- redirect stdout/stderr to the buffers ---------------------------
    hasSetStreams =
      typeof pyodide.setStdout === 'function' &&
      typeof pyodide.setStderr === 'function';
    if (hasSetStreams) {
      // Pyodide 0.26 native API (verified against the streams docs).
      pyodide.setStdout({
        batched: (s) => {
          stdoutBuf += s;
        },
      });
      pyodide.setStderr({
        batched: (s) => {
          stderrBuf += s;
        },
      });
    } else {
      // Fallback for a build without setStdout/setStderr: swap sys.stdout /
      // sys.stderr for a tiny Python shim that calls back into JS.
      pyodide.globals.set('__lab_write_out', (s) => {
        stdoutBuf += s;
      });
      pyodide.globals.set('__lab_write_err', (s) => {
        stderrBuf += s;
      });
      await pyodide.runPythonAsync(INSTALL_STREAMS_PY);
    }

    // --- override builtins.input to drain the queue ---------------------
    // Returns undefined (-> Python None) when the queue is empty; the Python
    // shim turns that into a real EOFError so a missing input line surfaces
    // as an ordinary Python traceback (the guide teaches it as a real error).
    pyodide.globals.set('__lab_next_line', (promptStr) => {
      if (!queue.length) return undefined;
      const v = queue.shift();
      stdoutBuf += (promptStr == null ? '' : promptStr) + v + '\n';
      return v;
    });
    await pyodide.runPythonAsync(INSTALL_INPUT_PY);

    // --- run the user code in a FRESH namespace ---------------------------
    // Every .run block on a page shares this one interpreter, so running user
    // code in pyodide.globals would let slide 4's variables leak into slide 9
    // (breaking a deliberate NameError demo) and would expose our __lab_*
    // helpers to a dir()/globals() demo. Each call therefore gets its own
    // globals dict; `globals` is a documented runPythonAsync option (Pyodide
    // FAQ, "How can I execute code in a custom namespace?" — named-only since
    // 0.21). The builtins.input override and the sys.stdout/sys.stderr
    // redirection are interpreter-global, not namespace-scoped, so they still
    // apply to code running here.
    const dictCls = pyodide.globals.get('dict');
    ns = dictCls();
    try { dictCls.destroy(); } catch (_) { /* best effort */ }
    ns.set('__name__', '__main__');
    await pyodide.runPythonAsync(code, { globals: ns });
  } catch (err) {
    ok = false;
    // PythonError.message is Pyodide's formatted Python traceback with no JS
    // frames (JS frames live on err.stack). Verified against the
    // type-conversions docs.
    const traceback =
      err && typeof err.message === 'string' ? err.message : String(err);
    if (stderrBuf && !stderrBuf.endsWith('\n')) stderrBuf += '\n';
    stderrBuf += traceback;
  } finally {
    // --- flush BEFORE unhooking the streams -------------------------------
    // Pyodide's stdout is line-buffered, so a trailing print("x", end="") is
    // still sitting in the buffer here; flushing after setStdout() reset would
    // send it to the console instead of our buffer, silently dropping it.
    try {
      pyodide.runPython('import sys; sys.stdout.flush(); sys.stderr.flush()');
    } catch (_) {
      /* best effort */
    }
    // --- ALWAYS restore default streams + builtins.input ------------------
    try {
      if (hasSetStreams) {
        pyodide.setStdout(); // no args -> restore default handler
        pyodide.setStderr();
      } else {
        await pyodide.runPythonAsync(RESTORE_STREAMS_PY);
      }
    } catch (_) {
      /* best effort */
    }
    try {
      await pyodide.runPythonAsync(RESTORE_INPUT_PY);
    } catch (_) {
      /* best effort */
    }
    for (const name of [
      '__lab_next_line',
      '__lab_write_out',
      '__lab_write_err',
      '__lab_input',
    ]) {
      try {
        pyodide.globals.delete(name);
      } catch (_) {
        /* not set — fine */
      }
    }
    if (ns) {
      try {
        ns.destroy();
      } catch (_) {
        /* best effort */
      }
      ns = null;
    }
  }

  return { stdout: stdoutBuf, stderr: stderrBuf, ok };
}

// ===== lab-widgets.mjs =====
// lab-widgets.mjs — quiz + predict grading for interactive lab decks.
//
// Two layers:
//   1. Pure grading helpers (parseAnswer, gradeQuiz) — no DOM, no deps,
//      unit-tested directly with `node --test`.
//   2. DOM upgraders (upgradeQuiz, upgradePredict, upgradeAll) that turn
//      plain deck markup into interactive widgets. These touch
//      document/window only when invoked (no top-level DOM access), so the
//      module imports cleanly under Node. They are exercised in a browser
//      at Task 6, not by node --test.
//
// Exports: parseAnswer, gradeQuiz, upgradeQuiz, upgradePredict, upgradeAll

// ---------------------------------------------------------------------------
// Pure grading helpers
// ---------------------------------------------------------------------------

// "B" -> {"B"};  "A,C" / "A, c" -> {"A","C"}  (upper-cased, trimmed, no blanks)
function parseAnswer(spec) {
  return new Set(
    String(spec == null ? '' : spec)
      .split(',')
      .map((s) => s.trim().toUpperCase())
      .filter(Boolean),
  );
}

// gradeQuiz(spec, chosen) -> { correct, expected: Set, chosen: Set }
// `chosen` may be a single string or an array of strings. `correct` is true
// iff the chosen set is exactly equal to the expected set.
function gradeQuiz(spec, chosen) {
  const expected = parseAnswer(spec);
  const list = Array.isArray(chosen) ? chosen : [chosen];
  const chosenSet = new Set(
    list
      .map((s) => String(s == null ? '' : s).trim().toUpperCase())
      .filter(Boolean),
  );
  const correct =
    chosenSet.size === expected.size &&
    [...chosenSet].every((v) => expected.has(v));
  return { correct, expected, chosen: chosenSet };
}

// ---------------------------------------------------------------------------
// DOM upgraders (browser-only at call time)
// ---------------------------------------------------------------------------

function ownerDoc(el) {
  return (el && el.ownerDocument) || (typeof document !== 'undefined' ? document : null);
}

// Wire one <div class="quiz" data-answer="…"> :
//   - option buttons carry [data-opt="A"]
//   - an optional <p class="why"> is hidden until the question is answered
//   - single-answer  : first click grades immediately
//   - multi-answer   : data-answer contains a comma; clicks toggle .chosen and
//                      a "Check" button (created if absent) grades
// Idempotent: a second call is a no-op once el.dataset.wired is set.
function upgradeQuiz(el) {
  if (!el || el.dataset.wired) return;
  el.dataset.wired = '1';

  const spec = el.dataset.answer || '';
  const expected = parseAnswer(spec);
  const multi = spec.includes(',');

  const opts = el.querySelectorAll ? [...el.querySelectorAll('[data-opt]')] : [];
  if (!opts.length) return;

  const why = el.querySelector ? el.querySelector('.why') : null;
  if (why) why.hidden = true;

  const grade = (values) => {
    if (el.dataset.answered) return;
    const result = gradeQuiz(spec, values);
    for (const btn of opts) {
      const val = String(btn.dataset.opt || '').trim().toUpperCase();
      if (result.chosen.has(val)) btn.classList.add('chosen');
      if (expected.has(val)) btn.classList.add('right');
      else if (result.chosen.has(val)) btn.classList.add('wrong');
      btn.disabled = true;
    }
    if (why) why.hidden = false;
    // Both paths matter: the stylesheet reveals .why via `.quiz.answered .why`
    // (so the base `display:none` wins before JS runs and there is no flash of
    // the explanation), while `hidden = false` covers the attribute.
    if (el.classList) el.classList.add('answered');
    el.dataset.answered = result.correct ? 'correct' : 'incorrect';
  };

  if (multi) {
    for (const btn of opts) {
      btn.addEventListener('click', () => {
        if (el.dataset.answered) return;
        btn.classList.toggle('chosen');
      });
    }
    const doc = ownerDoc(el);
    let check = el.querySelector ? el.querySelector('[data-check]') : null;
    if (!check && doc) {
      check = doc.createElement('button');
      check.type = 'button';
      check.className = 'check';
      check.dataset.check = '1';
      check.textContent = 'Check';
      el.appendChild(check);
    }
    if (check) {
      check.addEventListener('click', () => {
        const picked = opts
          .filter((b) => b.classList.contains('chosen'))
          .map((b) => b.dataset.opt);
        // Check with nothing selected is a no-op, not a permanent "incorrect"
        // lock — grade() disables every option and can never be re-run.
        if (!picked.length) return;
        grade(picked);
      });
    }
  } else {
    for (const btn of opts) {
      btn.addEventListener('click', () => grade([btn.dataset.opt]));
    }
  }
}

// Wire one <div class="predict"> holding prompt markup and a
// <pre class="answer" hidden>. Injects a "Reveal answer ▾" button that
// unhides the <pre> and runs window.hljs over it when available.
// Idempotent via el.dataset.wired.
function upgradePredict(el) {
  if (!el || el.dataset.wired) return;
  el.dataset.wired = '1';

  const pre = el.querySelector ? el.querySelector('pre.answer') : null;
  if (!pre) return;
  pre.hidden = true;

  const doc = ownerDoc(el);
  if (!doc) return;

  const btn = doc.createElement('button');
  btn.type = 'button';
  // NOT "reveal" — that class is reveal.js' own root-element class and every
  // stylesheet rule in the wild is written as `.reveal <something>`.
  btn.className = 'reveal-btn';
  btn.textContent = 'Reveal answer ▾';
  btn.addEventListener('click', () => {
    pre.hidden = false;
    btn.hidden = true;
    const hljs = typeof window !== 'undefined' ? window.hljs : null;
    if (!hljs || typeof hljs.highlightElement !== 'function') return;
    const target = pre.querySelector('code') || pre;
    // Skip if we — or reveal.js' RevealHighlight, which stamps
    // data-highlighted="yes" per highlight.js — already highlighted it.
    // Avoids highlight.js' "Element previously highlighted" console.warn.
    if (pre.dataset.highlighted || target.dataset.highlighted) return;
    pre.dataset.highlighted = '1';
    target.dataset.highlighted = '1';
    hljs.highlightElement(target);
  });
  el.insertBefore(btn, pre);
}

// Upgrade every .quiz / .predict under `root` (defaults to document).
function upgradeAll(root = document) {
  if (!root || !root.querySelectorAll) return;
  root.querySelectorAll('.quiz').forEach((el) => upgradeQuiz(el));
  root.querySelectorAll('.predict').forEach((el) => upgradePredict(el));
}

// ===== lab-draw.mjs =====
/* Draw overlay v3 */
/*
 * Lab Drawing Overlay
 *
 * Ported from ism3232/docs/week02_slides.html ("Draw overlay v3" IIFE)
 * into a reusable ES module. Call initDraw() once, after window.Reveal
 * has been initialized by the page.
 *
 * Uses BroadcastChannel to sync strokes between ALL same-origin windows
 * (presentation window + notes popup). No window references needed.
 *
 * Also handles the Reveal.js notes plugin iframe pattern:
 * the notes plugin opens /?controls=... as a popup containing an iframe
 * of the presentation. BroadcastChannel crosses that boundary automatically.
 */
function initDraw(opts = {}) {
  /* ── Idempotency guard ── */
  if (window.__labDrawInit) return;
  window.__labDrawInit = true;

  /* ── No-op on reveal PDF export ── */
  if (window.matchMedia && window.matchMedia('print').matches) return;
  if (location.search.indexOf('print-pdf') !== -1) return;

  /* ── Requires a Reveal global (already initialized by the caller) ── */
  if (!window.Reveal) return;

  var accent   = opts.accent || '#2dd4bf';
  /* Scope the channel to THIS deck: two different decks open in two tabs must
   * not cross-paint. The notes popup carries the same pathname, so the
   * presentation ↔ notes sync is unaffected. */
  var CHANNEL  = 'ismlab_draw:' + location.pathname;
  var bc       = null;

  /* "#2dd4bf" + alpha -> "rgba(45,212,191,alpha)" so the toolbar's active
   * state uses the course accent instead of a hardcoded teal. */
  function accentRGBA(a) {
    var h = String(accent).trim().replace('#', '');
    if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
    var n = parseInt(h, 16);
    if (h.length !== 6 || isNaN(n)) return 'rgba(45,212,191,' + a + ')';
    return 'rgba(' + ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255) + ',' + a + ')';
  }

  /* BroadcastChannel — supported in all modern browsers */
  try { bc = new BroadcastChannel(CHANNEL); } catch (e) { bc = null; }

  /* ── State ── */
  var drawMode = false;
  var erasing  = false;
  var col      = accent;
  var sz       = 5;
  var active   = false;   /* pointer currently down */
  var lx = 0, ly = 0;
  var strokes  = {};      /* slideKey → array of stroke segments */

  /* ── Canvas — full-viewport fixed overlay ── */
  var canvas      = document.createElement('canvas');
  canvas.id       = 'labdraw-canvas';
  canvas.style.cssText = 'position:fixed;top:0;left:0;width:100vw;height:100vh;' +
                          'pointer-events:none;z-index:799;';
  document.body.appendChild(canvas);

  function fit() {
    canvas.width  = window.innerWidth;
    canvas.height = window.innerHeight;
    redraw(key());
  }
  window.addEventListener('resize', fit);

  /* ── Slide key ── */
  function key() {
    try {
      var s = Reveal.getState();
      return s.indexh + ',' + s.indexv;
    } catch (e) { return '0,0'; }
  }

  /* ── Normalised coords (survive resize & window-size differences) ── */
  function toNorm(x, y) {
    return [x / window.innerWidth, y / window.innerHeight];
  }
  function fromNorm(nx, ny) {
    return [nx * window.innerWidth, ny * window.innerHeight];
  }

  /* ── Rendering ── */
  function renderSeg(seg) {
    var ctx = canvas.getContext('2d');
    var p0 = fromNorm(seg[0], seg[1]);
    var p1 = fromNorm(seg[2], seg[3]);
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(p0[0], p0[1]);
    ctx.lineTo(p1[0], p1[1]);
    if (seg[6]) {                         /* erasing */
      ctx.globalCompositeOperation = 'destination-out';
      ctx.strokeStyle = 'rgba(0,0,0,1)';
      ctx.lineWidth   = seg[5] * 4;
    } else {
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = seg[4];           /* colour */
      ctx.lineWidth   = seg[5];           /* size */
    }
    ctx.lineCap  = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  function redraw(k) {
    var ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    var segs = strokes[k];
    if (segs) segs.forEach(renderSeg);
  }

  /* ── Add + broadcast a segment ── */
  function addSeg(k, seg) {
    if (!strokes[k]) strokes[k] = [];
    strokes[k].push(seg);
  }

  function broadcastSeg(k, seg) {
    if (!bc) return;
    try { bc.postMessage({ t: 'seg', k: k, seg: seg }); } catch (e) {}
  }

  function broadcastClear(k) {
    if (!bc) return;
    try { bc.postMessage({ t: 'clear', k: k }); } catch (e) {}
  }

  function broadcastClearAll() {
    if (!bc) return;
    try { bc.postMessage({ t: 'clearAll' }); } catch (e) {}
  }

  /* ── Receive from other windows ── */
  if (bc) {
    bc.onmessage = function (ev) {
      var d = ev.data;
      if (!d) return;
      if (d.t === 'seg') {
        addSeg(d.k, d.seg);
        if (d.k === key()) renderSeg(d.seg);
      } else if (d.t === 'clear') {
        strokes[d.k] = [];
        if (d.k === key()) redraw(d.k);
      } else if (d.t === 'clearAll') {
        strokes = {};
        redraw(key());
      }
    };
  }

  /* ── Pointer events ── */
  function getXY(e) {
    if (e.touches && e.touches.length) {
      return [e.touches[0].clientX, e.touches[0].clientY];
    }
    return [e.clientX, e.clientY];
  }

  function down(e) {
    if (!drawMode) return;
    e.preventDefault();
    active = true;
    var xy = getXY(e);
    var n  = toNorm(xy[0], xy[1]);
    lx = n[0]; ly = n[1];
  }

  function move(e) {
    if (!active || !drawMode) return;
    e.preventDefault();
    var xy = getXY(e);
    var n  = toNorm(xy[0], xy[1]);
    var seg = [lx, ly, n[0], n[1], col, sz, erasing];
    lx = n[0]; ly = n[1];
    var k = key();
    addSeg(k, seg);
    renderSeg(seg);
    broadcastSeg(k, seg);
  }

  function up() { active = false; }

  canvas.addEventListener('mousedown',  down);
  canvas.addEventListener('mousemove',  move);
  canvas.addEventListener('mouseup',    up);
  canvas.addEventListener('mouseleave', up);
  canvas.addEventListener('touchstart', down, { passive: false });
  canvas.addEventListener('touchmove',  move, { passive: false });
  canvas.addEventListener('touchend',   up);

  /* ── Toggle draw mode ── */
  function setMode(on) {
    drawMode = on;
    canvas.style.pointerEvents = on ? 'all' : 'none';
    canvas.style.cursor        = on ? 'crosshair' : 'default';
    var tb = document.getElementById('labdraw-toolbar');
    if (tb) tb.style.outline = on ? '2px solid ' + accentRGBA('.5') : 'none';
    var tog = document.getElementById('dtog');
    if (tog) {
      tog.style.background  = on ? accentRGBA('.35') : 'rgba(255,255,255,.08)';
      tog.style.color       = on ? accent : '#ccc';
    }
    /* Hide reveal controls while drawing so clicks don't navigate */
    var ctrl = document.querySelector('.reveal > .controls');
    if (ctrl) ctrl.style.display = on ? 'none' : '';
  }

  /* ── Keyboard: D ── */
  document.addEventListener('keydown', function (e) {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
    if (e.key === 'd' || e.key === 'D') setMode(!drawMode);
  });

  /* ── Slide change ── */
  Reveal.on('slidechanged', function () {
    active = false;
    redraw(key());
  });

  /* ── Toolbar ── */
  var tb = document.createElement('div');
  tb.id  = 'labdraw-toolbar';
  tb.style.cssText = [
    'position:fixed', 'bottom:10px', 'right:10px', 'z-index:900',
    'display:flex', 'align-items:center', 'gap:5px', 'flex-wrap:wrap',
    'background:rgba(8,10,20,.92)', 'border:1px solid rgba(255,255,255,.13)',
    'border-radius:10px', 'padding:6px 9px',
    'backdrop-filter:blur(14px)', '-webkit-backdrop-filter:blur(14px)',
    'box-shadow:0 4px 24px rgba(0,0,0,.55)',
    'font-family:monospace', 'font-size:11px',
    'opacity:.5', 'transition:opacity .2s',
    'user-select:none', '-webkit-user-select:none',
  ].join(';');
  tb.onmouseenter = function () { this.style.opacity = '1'; };
  tb.onmouseleave = function () { this.style.opacity = drawMode ? '1' : '.5'; };
  document.body.appendChild(tb);

  /* ── Toolbar helpers ── */
  function btn(txt, cb, title, id) {
    var b = document.createElement('button');
    b.textContent = txt;
    if (title) b.title = title;
    if (id)    b.id    = id;
    b.style.cssText = [
      'font-family:monospace', 'font-size:11px', 'cursor:pointer',
      'padding:4px 9px', 'border-radius:5px',
      'border:1px solid rgba(255,255,255,.14)',
      'background:rgba(255,255,255,.08)', 'color:#ccc',
      'transition:.15s', 'white-space:nowrap',
    ].join(';');
    b.onmouseover = function () { b.style.background='rgba(255,255,255,.22)'; b.style.color='#fff'; };
    b.onmouseout  = function () {
      b.style.background = b._on ? 'rgba(255,255,255,.25)' : 'rgba(255,255,255,.08)';
      b.style.color      = b._on ? '#fff' : '#ccc';
    };
    b.onclick = cb;
    return b;
  }

  function dot(c, lbl, first) {
    var d = document.createElement('span');
    d.className = 'dcdot';
    d.title     = lbl;
    d.style.cssText = 'width:15px;height:15px;border-radius:50%;' +
      'background:' + c + ';cursor:pointer;display:inline-block;' +
      'border:2px solid ' + (first ? '#fff' : 'transparent') + ';' +
      'flex-shrink:0;transition:border-color .15s;';
    d.onclick = function () {
      col = c; erasing = false;
      document.querySelectorAll('.dcdot').forEach(function (x) { x.style.borderColor = 'transparent'; });
      d.style.borderColor = '#fff';
      if (eraserB) { eraserB._on = false; eraserB.style.background='rgba(255,255,255,.08)'; eraserB.style.color='#ccc'; }
    };
    return d;
  }

  function sep() {
    var s = document.createElement('span');
    s.style.cssText = 'width:1px;height:18px;background:rgba(255,255,255,.15);flex-shrink:0;';
    return s;
  }

  /* Toggle */
  var togB = btn('✏ Draw', function () { setMode(!drawMode); }, 'Toggle drawing  [D]', 'dtog');

  /* Colours */
  var palette = [
    [accent,   'Accent', true],
    ['#ffffff','White',  false],
    ['#ff6b6b','Red',    false],
    ['#4ade80','Green',  false],
    ['#38bdf8','Blue',   false],
    ['#f97316','Orange', false],
    ['#c084fc','Purple', false],
  ];
  var colDots = palette.map(function (p) { return dot(p[0], p[1], p[2]); });

  /* Sizes */
  var sizes = [[3,'S'],[5,'M'],[10,'L'],[18,'XL']];
  var szBtns = sizes.map(function (p) {
    var b = btn(p[1], null, 'Brush ' + p[1]);
    b.onclick = function () {
      sz = p[0]; erasing = false;
      szBtns.forEach(function (x) { x._on=false; x.style.background='rgba(255,255,255,.08)'; x.style.color='#ccc'; });
      if (eraserB) { eraserB._on=false; eraserB.style.background='rgba(255,255,255,.08)'; eraserB.style.color='#ccc'; }
      b._on=true; b.style.background='rgba(255,255,255,.25)'; b.style.color='#fff';
    };
    if (p[0]===5) { b._on=true; b.style.background='rgba(255,255,255,.25)'; b.style.color='#fff'; }
    return b;
  });

  /* Eraser */
  var eraserB = btn('⌫', null, 'Eraser');
  eraserB.onclick = function () {
    erasing = !erasing;
    eraserB._on = erasing;
    eraserB.style.background = erasing ? 'rgba(251,191,36,.4)' : 'rgba(255,255,255,.08)';
    eraserB.style.color      = erasing ? '#fbbf24' : '#ccc';
    if (erasing) { colDots.forEach(function(d){d.style.borderColor='transparent';}); }
  };

  /* Clear */
  var clearB = btn('🗑', function () {
    var k = key();
    strokes[k] = [];
    redraw(k);
    broadcastClear(k);
  }, 'Clear this slide');

  var clearAllB = btn('🗑 All', function () {
    strokes = {};
    redraw(key());
    broadcastClearAll();
  }, 'Clear all');

  /* Assemble */
  [togB, sep()]
    .concat(colDots)
    .concat([sep()])
    .concat(szBtns)
    .concat([sep(), eraserB, sep(), clearB, clearAllB])
    .forEach(function (el) { tb.appendChild(el); });

  /* ── Init ── */
  fit();

}

// ===== lab-slides.js =====
// lab-slides.js — framework entry for interactive lab decks.
//
// A deck loads this last, as <script type="module">, AFTER the classic
// reveal.js CDN scripts (which set window.Reveal / RevealHighlight /
// RevealNotes). On import it initializes reveal.js; on the 'ready' event it
// upgrades every interactive component (.quiz, .predict, .run) and starts the
// drawing overlay.
//
// Byte-identical between the ISM3232 and ISM2411 submodules — no
// course-specific strings live here; the accent is read from the --accent CSS
// custom property that lab-slides.css defines per course.


const Reveal = window.Reveal;

// --- reveal.js init (auto-runs on import) ----------------------------------
Reveal.initialize({
  width: 1180,
  height: 760,
  margin: 0.06,
  hash: true,
  slideNumber: 'c/t',
  transition: 'fade',
  plugins: [window.RevealHighlight, window.RevealNotes].filter(Boolean),
});
Reveal.on('ready', bootstrap);

// element -> its run function, so 'slidechanged' can fire data-autorun widgets
const RUNNERS = new WeakMap();

function bootstrap() {
  upgradeAll(document);
  upgradeRunners(document);
  const accent = getComputedStyle(document.documentElement)
    .getPropertyValue('--accent')
    .trim() || '#2dd4bf';
  initDraw({ accent });

  Reveal.on('slidechanged', (ev) => {
    const slide = ev && ev.currentSlide;
    if (!slide || !slide.querySelectorAll) return;
    slide.querySelectorAll('div.run[data-autorun]').forEach((el) => {
      const fn = RUNNERS.get(el);
      if (fn && !el.dataset.autorunDone) {
        el.dataset.autorunDone = '1';
        fn();
      }
    });
  });
}

// --- error text helper ----------------------------------------------------
function errText(e) {
  return String((e && e.message) || e);
}

// --- data-stdin parsing (carry-in 1) ------------------------------------
// Newline- or "&#10;"-separated; a trailing empty line is dropped.
function parseStdin(raw) {
  const parts = String(raw == null ? '' : raw).split(/\r?\n|&#10;/);
  if (parts.length && parts[parts.length - 1] === '') parts.pop();
  return parts;
}

// --- matplotlib → PNG (only for data-packages="…,matplotlib") -----------
// Forces the headless AGG backend, then AFTER the user code tries to grab any
// open figure and print it as a base64 PNG on a "__LABPNG__" sentinel line
// (buildPython's writeStdout turns that into an <img>). Guarded so a block that
// draws nothing stays silent and a matplotlib import error is not masked.
//
// The capture ALWAYS ends with plt.close("all") so figures never survive into
// the next block — otherwise a later block that draws nothing would re-emit the
// previous block's chart (every run shares one Pyodide interpreter, and
// pyplot's figure registry is interpreter-global, not namespace-local).
function wrapFigure(code) {
  return (
    'import matplotlib; matplotlib.use("AGG")\n' +
    code +
    '\ntry:\n' +
    '    import matplotlib.pyplot as _p, io as _io, base64 as _b64\n' +
    '    if _p.get_fignums():\n' +
    '        _bf = _io.BytesIO(); _p.savefig(_bf, format="png")\n' +
    '        print("__LABPNG__" + _b64.b64encode(_bf.getvalue()).decode())\n' +
    '    _p.close("all")\n' +
    'except Exception:\n' +
    '    pass\n'
  );
}

// --- component upgrade ---------------------------------------------------
function upgradeRunners(root) {
  if (!root || !root.querySelectorAll) return;
  root.querySelectorAll('div.run').forEach((el) => {
    if (el.dataset.wired) return;
    el.dataset.wired = '1';
    const lang = el.dataset.lang === 'shell' ? 'shell' : 'python';
    // el.textContent is already HTML-unescaped by the browser.
    const src = (el.textContent || '').replace(/\r\n/g, '\n').trim();
    el.textContent = '';
    if (lang === 'shell') buildShell(el, src);
    else buildPython(el, src);
  });
}

// --- python widget -----------------------------------------------------
function buildPython(el, src) {
  const wantStdin = /\binput\s*\(/.test(src) || 'stdin' in el.dataset;
  let stdinBox = null;
  if (wantStdin) {
    stdinBox = document.createElement('textarea');
    stdinBox.className = 'stdin';
    stdinBox.setAttribute('aria-label', 'standard input');
    stdinBox.placeholder = 'stdin — one value per line';
    if ('stdin' in el.dataset) stdinBox.value = parseStdin(el.dataset.stdin).join('\n');
    el.appendChild(stdinBox);
  }

  // data-readonly python = the source shown as a static highlighted block +
  // Run + output pane (no editable textarea). upgradeRunners has already
  // emptied el, so without this the pane would render a bare Run button over
  // nothing. (readonly SHELL differs: static code only, no Run — see
  // buildShell.)
  let editor = null;
  if ('readonly' in el.dataset) {
    renderStaticCode(el, src, 'python');
  } else {
    editor = document.createElement('textarea');
    editor.className = 'code';
    editor.spellcheck = false;
    editor.value = src;
    editor.addEventListener('keydown', (ev) => {
      if (ev.key !== 'Tab') return;
      ev.preventDefault();
      const s = editor.selectionStart;
      const e = editor.selectionEnd;
      editor.value = editor.value.slice(0, s) + '  ' + editor.value.slice(e);
      editor.selectionStart = editor.selectionEnd = s + 2;
    });
    el.appendChild(editor);
  }

  const bar = document.createElement('div');
  bar.className = 'bar';
  const runBtn = document.createElement('button');
  runBtn.type = 'button';
  runBtn.className = 'go';
  runBtn.textContent = 'Run ▶';
  bar.appendChild(runBtn);
  if (editor) {
    const resetBtn = document.createElement('button');
    resetBtn.type = 'button';
    resetBtn.className = 'reset';
    resetBtn.textContent = 'reset';
    resetBtn.addEventListener('click', () => { editor.value = src; });
    bar.appendChild(resetBtn);
  }
  el.appendChild(bar);

  const status = document.createElement('div');
  status.className = 'status';
  el.appendChild(status);

  // --- data-packages preload (ISM2411 data weeks) ----------------------
  // Comma-separated Pyodide package list, e.g. "pandas" or "pandas,matplotlib".
  // The Run button's FIRST activation preloads them; later Runs skip it. A
  // block WITHOUT data-packages is completely unaffected — `pkgs` is empty and
  // every branch below is guarded on `pkgs.length`.
  const pkgs = (el.dataset.packages || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
  const wrapFig = pkgs.includes('matplotlib');
  let pkgsLoaded = false;
  let pkgStatus = null;
  if (pkgs.length) {
    pkgStatus = document.createElement('span');
    pkgStatus.className = 'pkg-status';
    el.appendChild(pkgStatus);
  }

  const out = document.createElement('pre');
  out.className = 'out';
  el.appendChild(out);

  const onStatus = (s) => {
    if (s === 'loading') {
      runBtn.disabled = true;
      runBtn.textContent = 'starting Python…';
      status.textContent = 'loading the Python runtime…';
    } else {
      status.textContent = '';
    }
  };

  const writeErr = (text) => {
    const span = document.createElement('span');
    span.className = 'err';
    span.textContent = text;
    out.appendChild(span);
  };

  // Only used for matplotlib blocks: split stdout on our sentinel lines and
  // render each captured figure as an <img> in place of that line.
  const FIG_RE = /^__LABPNG__([A-Za-z0-9+/=]+)$/;
  const writeStdout = (text) => {
    const buf = [];
    const flush = () => {
      if (buf.length) {
        out.appendChild(document.createTextNode(buf.join('\n')));
        buf.length = 0;
      }
    };
    for (const line of String(text).split('\n')) {
      const m = FIG_RE.exec(line);
      if (m) {
        flush();
        const img = document.createElement('img');
        img.className = 'fig';
        img.alt = 'matplotlib figure';
        img.src = 'data:image/png;base64,' + m[1];
        out.appendChild(img);
      } else {
        buf.push(line);
      }
    }
    flush();
  };

  const execute = async () => {
    const code = editor ? editor.value : src;
    const stdin = stdinBox ? parseStdin(stdinBox.value) : [];
    out.textContent = '';
    runBtn.disabled = true;
    try {
      if (pkgs.length && !pkgsLoaded) {
        if (pkgStatus) pkgStatus.textContent = 'loading packages…';
        try {
          await loadPackages(pkgs);
          pkgsLoaded = true;
        } finally {
          if (pkgStatus) pkgStatus.textContent = '';
        }
      }
      // runPython may REJECT on a Pyodide loader failure (carry-in 3), and
      // loadPackages above rejects when offline — both land in catch, no throw.
      const res = await runPython(wrapFig ? wrapFigure(code) : code, { stdin, onStatus });
      if (wrapFig) writeStdout(res.stdout || '');
      else out.textContent = res.stdout || '';
      // Separate stdout from a traceback with exactly one newline — stdout that
      // already ends in "\n" (always true after an input() echo) must not get a
      // blank line before "Traceback", so the widget matches the s-out slides.
      if (res.stderr) {
        writeErr((res.stdout && !res.stdout.endsWith('\n') ? '\n' : '') + res.stderr);
      }
    } catch (e) {
      writeErr(errText(e));
    } finally {
      runBtn.disabled = false;
      runBtn.textContent = 'Run ▶';
    }
  };

  runBtn.addEventListener('click', execute);
  RUNNERS.set(el, execute);

  if ('autorun' in el.dataset) {
    const slide = el.closest('section');
    if (slide && slide.classList.contains('present') && !el.dataset.autorunDone) {
      el.dataset.autorunDone = '1';
      execute();
    }
  }
}

// --- readonly static code block -----------------------------------------
// Renders `src` as a plain <pre><code class="language-*">. No interactive UI.
//
// reveal.js 4.6.1's RevealHighlight plugin runs during Reveal.initialize(),
// i.e. BEFORE the 'ready' event where these upgraders run — so it never sees
// these nodes. Highlight them ourselves, and stamp data-highlighted so the
// .predict reveal guard (and any later pass) does not double-highlight.
function renderStaticCode(el, src, lang) {
  const pre = document.createElement('pre');
  pre.className = 'static';
  const code = document.createElement('code');
  code.className = 'language-' + lang;
  code.textContent = src;
  pre.appendChild(code);
  el.appendChild(pre);
  try {
    if (window.hljs && typeof window.hljs.highlightElement === 'function') {
      window.hljs.highlightElement(code);
    }
  } catch (_) {
    /* highlighting is cosmetic — never break the slide */
  }
  code.dataset.highlighted = '1';
}

// --- shell (zsh terminal) widget ------------------------------------------
function buildShell(el, src) {
  // data-readonly shell steps (git / venv / pip — not runnable in the
  // emulator) render as a static block: no "Run all", no prompt/input line,
  // no createShell transcript. Mirrors buildPython's readonly handling.
  if ('readonly' in el.dataset) {
    renderStaticCode(el, src, 'bash');
    return;
  }
  el.classList.add('shell');
  let seed = {};
  try { seed = el.dataset.fs ? JSON.parse(el.dataset.fs) : {}; } catch (_) { seed = {}; }
  const shell = createShell(seed);
  // python3 <file> / python3 -c "<code>" in the emulator delegates to Pyodide.
  // Returns BOTH streams so a Python traceback lands in the transcript as .err
  // instead of being swallowed.
  shell.pythonRunner = async (code) => {
    try {
      const r = await runPython(code);
      return { out: r.stdout, err: r.stderr };
    } catch (e) {
      return { out: '', err: errText(e) };
    }
  };

  const term = document.createElement('div');
  term.className = 'term';
  el.appendChild(term);

  const cli = document.createElement('div');
  cli.className = 'cli';
  const ps1 = document.createElement('span');
  ps1.className = 'ps1';
  const input = document.createElement('input');
  input.type = 'text';
  input.autocapitalize = 'off';
  input.autocomplete = 'off';
  input.spellcheck = false;
  cli.appendChild(ps1);
  cli.appendChild(input);
  el.appendChild(cli);

  const bar = document.createElement('div');
  bar.className = 'bar';
  const runAll = document.createElement('button');
  runAll.type = 'button';
  runAll.textContent = 'Run all';
  bar.appendChild(runAll);
  el.appendChild(bar);

  const syncPrompt = () => { ps1.textContent = prompt(shell) + ' '; };
  const write = (text, cls) => {
    if (text == null || text === '') return;
    const span = document.createElement('span');
    if (cls) span.className = cls;
    span.textContent = text;
    term.appendChild(span);
    term.scrollTop = term.scrollHeight;
  };

  const submit = async (line) => {
    write(prompt(shell) + ' ' + line + '\n', 'echo');
    const res = run(shell, line);
    if (res.cleared) term.textContent = '';
    write(res.out, 'out');
    write(res.err, 'err');
    if (res.async) {
      try {
        const done = await res.async;
        write(done.out, 'out');
        write(done.err, 'err');
      } catch (e) {
        write(errText(e), 'err');
      }
    }
    syncPrompt();
  };

  input.addEventListener('keydown', (ev) => {
    if (ev.key !== 'Enter') return;
    ev.preventDefault();
    const line = input.value;
    input.value = '';
    if (line.trim() === '') return; // skip blank submissions (carry-in 4)
    submit(line);
  });

  runAll.addEventListener('click', async () => {
    runAll.disabled = true;
    // Strip a trailing "# comment" only when the line carries no quotes.
    const lines = src.split('\n').map((l) => (/['"]/.test(l) ? l : l.replace(/\s+#.*$/, '')).trim());
    for (const line of lines) {
      if (line === '' || line.startsWith('#')) continue;
      await submit(line);
    }
    runAll.disabled = false;
    input.focus();
  });

  syncPrompt();
}

})();
